// Gelen parametreleri işle
const body = $input.item.json.body;

const examType = body.examType || 'TYT';
const subject = body.subject || 'Matematik';
const topic = body.topic || 'Genel';
const difficulty = body.difficulty || 'Orta';

// GPT-4o için prompt oluştur
const prompt = `Sen bir YKS (Yükseköğretim Kurumları Sınavı) soru hazırlama uzmanısın.

Aşağıdaki kriterlere uygun bir ${examType} sorusu hazırla:

**Ders:** ${subject}
**Konu:** ${topic}
**Zorluk Seviyesi:** ${difficulty}

**Gereksinimler:**
1. Soru Türkiye'deki YKS formatına uygun olmalı
2. 4 şıklı (A, B, C, D) çoktan seçmeli
3. Sorunun sadece bir doğru cevabı olmalı
4. ${difficulty} seviyesine uygun olmalı
   - Kolay: Temel bilgi ve kavrama
   - Orta: Kavrama, uygulama ve analiz
   - Zor: Analiz, sentez ve değerlendirme
5. MEB müfredatına uygun olmalı
6. Gerçekçi ve ölçülebilir olmalı
7. Net bir dil kullan, belirsizlikten kaçın
8. Çeldiriciler mantıklı olmalı

**Çıktı Formatı (JSON):**
{
  "soru": "Soru metni burada",
  "secenekler": {
    "A": "Seçenek A metni",
    "B": "Seçenek B metni",
    "C": "Seçenek C metni",
    "D": "Seçenek D metni"
  },
  "dogruCevap": "A",
  "aciklama": "Sorunun çözüm açıklaması",
  "konu": "${topic}",
  "zorluk": "${difficulty}",
  "ders": "${subject}",
  "examType": "${examType}"
}

Sadece JSON formatında yanıt ver, başka açıklama ekleme.`;

return {
  json: {
    examType,
    subject,
    topic,
    difficulty,
    prompt
  }
};

// GPT-4o yanıtını parse et
let response = $input.item.json.message?.content || $input.item.json.text || '';

// JSON formatını temizle
let cleanedResponse = response.trim();
if (cleanedResponse.startsWith('```json')) {
  cleanedResponse = cleanedResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '');
} else if (cleanedResponse.startsWith('```')) {
  cleanedResponse = cleanedResponse.replace(/```\n?/g, '');
}

try {
  const questionData = JSON.parse(cleanedResponse);

  // Timestamp ve ID ekle
  questionData.id = `q_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  questionData.createdAt = new Date().toISOString();
  questionData.status = 'active';

  return {
    json: {
      success: true,
      question: questionData
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: 'JSON parse hatası: ' + error.message,
      rawResponse: cleanedResponse
    }
  };
}

// Simüle edilmiş kullanıcı performans verisi
// Gerçek uygulamada PostgreSQL'den çekilecek

const userId = $input.item.json.params.userId;

// Örnek veri yapısı
const performanceData = {
  userId: userId,
  username: `Kullanıcı_${userId}`,
  subjects: [
    { ders: 'Matematik', toplam: 45, dogru: 32, yanlis: 10, bos: 3 },
    { ders: 'Türkçe', toplam: 40, dogru: 35, yanlis: 4, bos: 1 },
    { ders: 'Fizik', toplam: 30, dogru: 18, yanlis: 10, bos: 2 },
    { ders: 'Kimya', toplam: 25, dogru: 15, yanlis: 8, bos: 2 },
    { ders: 'Biyoloji', toplam: 20, dogru: 16, yanlis: 3, bos: 1 },
    { ders: 'Tarih', toplam: 15, dogru: 12, yanlis: 2, bos: 1 },
    { ders: 'Coğrafya', toplam: 18, dogru: 14, yanlis: 3, bos: 1 }
  ]
};

// Toplam istatistikler hesapla
const totalQuestions = performanceData.subjects.reduce((sum, s) => sum + s.toplam, 0);
const totalCorrect = performanceData.subjects.reduce((sum, s) => sum + s.dogru, 0);
const totalWrong = performanceData.subjects.reduce((sum, s) => sum + s.yanlis, 0);
const totalEmpty = performanceData.subjects.reduce((sum, s) => sum + s.bos, 0);

// Ders bazında başarı yüzdesi hesapla
const subjectPerformance = performanceData.subjects.map(subject => ({
  ...subject,
  basari_yuzdesi: subject.toplam > 0 
    ? Math.round((subject.dogru / subject.toplam) * 100) 
    : 0
}));

// Güçlü ve zayıf yönleri belirle
const strongSubjects = subjectPerformance
  .filter(s => s.basari_yuzdesi >= 70)
  .map(s => s.ders);

const weakSubjects = subjectPerformance
  .filter(s => s.basari_yuzdesi < 50)
  .map(s => s.ders);

// Öneriler oluştur
const recommendations = [];

if (weakSubjects.length > 0) {
  recommendations.push(`🎯 Şu derslere daha fazla odaklanın: ${weakSubjects.join(', ')}`);
}

if (totalQuestions < 50) {
  recommendations.push('📚 Daha fazla soru çözmeye devam edin. Hedef: günde en az 20 soru!');
}

if (strongSubjects.length > 0) {
  recommendations.push(`💪 Güçlü olduğunuz dersler: ${strongSubjects.join(', ')}. Bu momentum'u koruyun!`);
}

if (totalEmpty > totalQuestions * 0.1) {
  recommendations.push('⚠️ Boş bırakma oranınız yüksek. Tahmin yaparak şansınızı deneyin!');
}

const overallSuccess = totalQuestions > 0 
  ? Math.round((totalCorrect / totalQuestions) * 100) 
  : 0;

if (overallSuccess >= 80) {
  recommendations.push('🌟 Harika gidiyorsun! Bu performansı sürdür!');
} else if (overallSuccess >= 60) {
  recommendations.push('👍 İyi bir performans. Biraz daha çaba ile zirveye ulaşabilirsin!');
} else {
  recommendations.push('💡 Temel konuları tekrar et ve düzenli çalış. Başarı yakın!');
}

return {
  json: {
    success: true,
    userId: userId,
    username: performanceData.username,
    summary: {
      totalQuestions,
      totalCorrect,
      totalWrong,
      totalEmpty,
      overallSuccess
    },
    subjectPerformance: subjectPerformance,
    insights: {
      strongSubjects,
      weakSubjects,
      recommendations
    },
    generatedAt: new Date().toISOString()
  }
};

// Örnek kullanıcı listesi
// Gerçek uygulamada PostgreSQL'den çekilecek

const activeUsers = [
